sys_script_include.script:
var OptionProcessorAjax = Class.create();
OptionProcessorAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    updateSelectedOptions: function() {
        var recordSysId = this.getParameter('sysparm_record_sys_id');
        var tableName = this.getParameter('sysparm_table_name');
        var optionsData = this.getParameter('sysparm_options_data');

        gs.info("OptionProcessorAjax (Initial Params): SysId: " + recordSysId + ", Table: " + tableName + ", OptionsData: " + optionsData);

        if (!recordSysId || !tableName || !optionsData || recordSysId == '-1') {
            gs.error("OptionProcessorAjax: Missing or invalid parameters. SysId: " + recordSysId + ", Table: " + tableName + ", Options: " + optionsData);
            return "error: Missing or invalid parameters. Is the record saved?";
        }

        try {
            var optionsObject = JSON.parse(optionsData);
            var selectedOptionNames = []; // This will store your desired output: ['trade_date','settlement_date']

            // Iterate over the properties of the optionsObject
            for (var key in optionsObject) {
                // Ensure the key is a direct property of the object (not from prototype chain)
                if (optionsObject.hasOwnProperty(key)) {
                    // If the checkbox was checked (value is true)
                    if (optionsObject[key] === true) {
                        selectedOptionNames.push(key); // Add the backend name (key) to the array
                    }
                }
            }

            // Convert the array to a JSON string for storing in the field
            var finalOutput = JSON.stringify(selectedOptionNames); 

            gs.info("OptionProcessorAjax: Final Output for Description: " + finalOutput);

            var gr = new GlideRecord(tableName);
            if (gr.get(recordSysId)) {
                // Set the value of your field (e.g., description). This will now store the JSON array string.
                gr.setValue('description', finalOutput); 
                gr.update();
                gs.info("OptionProcessorAjax: Successfully updated record " + recordSysId + " with options: " + finalOutput);
                return "success";
            } else {
                gs.error("OptionProcessorAjax: Record not found for SysId: " + recordSysId + " on Table: " + tableName);
                return "error: Record not found.";
            }
        } catch (e) {
            gs.error("OptionProcessorAjax: Server-side error processing options for record " + recordSysId + " on table " + tableName + ". Error: " + e.getMessage() + ", Stack: " + e.stack);
            return "error: " + e.getMessage();
        }
    },

    type: 'OptionProcessorAjax'
});
